import{_ as e,o,c as d,a3 as r}from"./chunks/framework.B02wg2PO.js";const p=JSON.parse('{"title":"Orchestrator Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/orchestrator-tools.md","filePath":"reference/orchestrator-tools.md"}'),a={name:"reference/orchestrator-tools.md"};function c(s,t,n,l,i,h){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="orchestrator-tools" tabindex="-1">Orchestrator Tools <a class="header-anchor" href="#orchestrator-tools" aria-label="Permalink to &quot;Orchestrator Tools&quot;">​</a></h1><p>PRIME&#39;s toolbelt is an MCP server (<code>saidi</code>) constructed per WebSocket connection and scoped to the connected operator. Tools are namespaced <code>mcp__saidi__&lt;name&gt;</code>.</p><h2 id="delegation" tabindex="-1">Delegation <a class="header-anchor" href="#delegation" aria-label="Permalink to &quot;Delegation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>delegate_to_project</code></td><td>Run a repo-scoped project agent. Takes the registry project, <code>mode</code> (<code>ask</code> | <code>work</code>), and the task</td></tr><tr><td><code>run_agent</code></td><td>Run a custom agent. A department lead is spawned with its own delegation tools</td></tr></tbody></table><p>Department leads additionally receive, scoped to their own department:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>delegate_to_specialist</code></td><td>Hand one task to one team member</td></tr><tr><td><code>delegate_to_specialists</code></td><td>Fan out to several team members in parallel</td></tr></tbody></table><h2 id="runs" tabindex="-1">Runs <a class="header-anchor" href="#runs" aria-label="Permalink to &quot;Runs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>start_run</code></td><td>Open a new Run from a brief</td></tr><tr><td><code>list_runs</code></td><td>Recent runs with status, project, preview</td></tr><tr><td><code>search_runs</code></td><td>Full-text search across briefs and threads</td></tr><tr><td><code>get_run</code></td><td>One run&#39;s full detail</td></tr><tr><td><code>reply_to_run</code></td><td>Send a message into a run&#39;s thread</td></tr><tr><td><code>control_run</code></td><td><code>pause</code> | <code>resume</code> | <code>halt</code> | <code>reopen</code> | <code>delete</code></td></tr><tr><td><code>resolve_run_approval</code></td><td>Approve or deny a pending approval gate</td></tr><tr><td><code>attach_run_assets</code></td><td>Attach produced files to the run</td></tr><tr><td><code>send_file</code></td><td>Deliver a file to the operator in chat</td></tr></tbody></table><h2 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;Memory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>remember</code></td><td>Semantically update memory — the curator merges, updates, or resolves contradictions rather than appending</td></tr></tbody></table><h2 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>list_projects</code></td><td>The registry</td></tr><tr><td><code>discover_projects</code></td><td>Scan configured roots for git repos</td></tr><tr><td><code>sync_projects</code></td><td>Reconcile the registry with disk</td></tr><tr><td><code>add_project</code> / <code>update_project</code> / <code>remove_project</code></td><td>Manage entries</td></tr></tbody></table><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>list_agents</code></td><td>Custom agents with department, lead flag, permission</td></tr><tr><td><code>create_agent</code></td><td>Scaffold <code>agents/&lt;name&gt;/AGENT.md</code></td></tr><tr><td><code>remove_agent</code></td><td>Delete the agent directory</td></tr><tr><td><code>add_skill</code></td><td>Write a skill into <code>agents/&lt;name&gt;/skills/</code></td></tr><tr><td><code>import_skill</code></td><td>Fetch a skill from a URL</td></tr><tr><td><code>add_mcp_server</code> / <code>remove_mcp_server</code></td><td>Edit the agent&#39;s <code>.mcp.json</code></td></tr></tbody></table><h2 id="automation" tabindex="-1">Automation <a class="header-anchor" href="#automation" aria-label="Permalink to &quot;Automation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>list_crons</code> / <code>create_cron</code> / <code>update_cron</code> / <code>delete_cron</code></td><td>Clock-triggered scheduled work</td></tr><tr><td><code>list_reflexes</code> / <code>create_reflex</code> / <code>update_reflex</code> / <code>delete_reflex</code></td><td>Event-triggered rules</td></tr><tr><td><code>raise_event</code></td><td>Emit a normalized event onto the bus by hand</td></tr></tbody></table><h2 id="activity" tabindex="-1">Activity <a class="header-anchor" href="#activity" aria-label="Permalink to &quot;Activity&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>search_activity</code></td><td>Cross-run search of what happened, when, and by whom — scoped to what the viewer may see</td></tr></tbody></table><h2 id="notes-on-behaviour" tabindex="-1">Notes on behaviour <a class="header-anchor" href="#notes-on-behaviour" aria-label="Permalink to &quot;Notes on behaviour&quot;">​</a></h2><ul><li><strong>Locking.</strong> <code>delegate_to_project</code> takes a repo lock keyed on the checkout; <code>run_agent</code> takes an agent lock. Concurrent delegations to the same target serialise.</li><li><strong>Permission and spend checks</strong> run before dispatch. A blocked call returns a reason rather than failing opaquely.</li><li><strong>Results are clipped</strong> against a shared context budget, with a floor per result in a batch so one verbose agent cannot starve the rest.</li><li><strong>Every settled call</strong> appends a <code>RunUsageEntry</code> to the run&#39;s <code>usageLog</code>.</li></ul>',20)])])}const b=e(a,[["render",c]]);export{p as __pageData,b as default};
